NL_CAL = [
 ('su-open', 'window-start', NL_UVR + ', art. 10', ['10'], W(3, 1), 'Se abre el plazo de la solicitud (Gecombineerde opgave) de pagos directos (1 de marzo del año de solicitud).',
  tr('The direct-payment application (Gecombineerde opgave) window opens (1 March of the application year).', "La période de dépôt de la demande de paiements directs (Gecombineerde opgave) s'ouvre (1er mars de l'année de demande).", "Si apre la finestra per la domanda di pagamenti diretti (Gecombineerde opgave) (1° marzo dell'anno di domanda).")),
 ('su-close', 'deadline', NL_UVR + ', art. 10', ['10'], W(5, 15), 'Termina el plazo ordinario de la solicitud (15 de mayo, que también es la fecha de referencia). Si cae en sábado o domingo, pasa al siguiente día hábil.',
  tr('The ordinary application deadline ends (15 May, which is also the reference date). If it falls on a Saturday or Sunday it moves to the next working day.', "La date limite ordinaire de la demande (15 mai, qui est aussi la date de référence). Si elle tombe un samedi ou un dimanche, elle passe au jour ouvrable suivant.", "Scade il termine ordinario della domanda (15 maggio, che è anche la data di riferimento). Se cade di sabato o domenica, slitta al giorno lavorativo successivo.")),
 ('changes-close', 'deadline', NL_UVR + ', art. 10', ['10'], W(10, 15), 'Último día para comunicar cambios en la solicitud (15 de octubre del año de solicitud).',
  tr('Last day to report changes to the application (15 October of the application year).', "Dernier jour pour signaler des modifications de la demande (15 octobre de l'année de demande).", "Ultimo giorno per comunicare modifiche alla domanda (15 ottobre dell'anno di domanda).")),
 ('payment-open', 'window-start', NL_EU44, ['44'], W(12, 1), 'Empieza el período de pago de los pagos directos (1 de diciembre); RVO empieza a pagar ese día. Base: art. 44 del Reglamento (UE) 2021/2116, leído en copia no oficial.',
  tr('The payment period for direct payments starts (1 December); RVO starts paying that day. Basis: art. 44 of Regulation (EU) 2021/2116, read in an unofficial copy.', "La période de paiement des paiements directs s'ouvre (1er décembre) ; le RVO commence à payer ce jour-là. Base : art. 44 du règlement (UE) 2021/2116, lu dans une copie non officielle.", "Si apre il periodo di pagamento dei pagamenti diretti (1° dicembre); l'RVO inizia a pagare quel giorno. Base: art. 44 del regolamento (UE) 2021/2116, letto in una copia non ufficiale.")),
 ('decision-close', 'deadline', NL_UVR + ', art. 10', ['10'], W(6, 30, 1), 'Fecha límite para que el ministro decida sobre las solicitudes del año anterior (30 de junio).',
  tr('Deadline for the minister to decide on the previous year\'s applications (30 June).', "Date limite pour que le ministre statue sur les demandes de l'année précédente (30 juin).", "Scadenza entro cui il ministro decide sulle domande dell'anno precedente (30 giugno).")),
]

NL_OVR = [
 (2026, 'su-close', '2026-05-18', NL_RVO26_VER, 'En 2026 el plazo de la solicitud se amplió del 15 de mayo al lunes 18 de mayo, porque el viernes 15 de mayo, día siguiente a la Ascensión, está equiparado legalmente a festivo. La fecha de referencia siguió siendo el 15 de mayo de 2026. Fuente: RVO (no se ha leído la modificación del reglamento Stcrt. 2026, 16532).',
  tr('In 2026 the application deadline was extended from 15 May to Monday 18 May, because Friday 15 May, the day after Ascension Day, is legally treated as a public holiday. The reference date stayed 15 May 2026. Source: RVO (the regulation amendment Stcrt. 2026, 16532 was not read).', "En 2026, la date limite de la demande a été prorogée du 15 mai au lundi 18 mai, parce que le vendredi 15 mai, lendemain de l'Ascension, est légalement assimilé à un jour férié. La date de référence est restée le 15 mai 2026. Source : RVO (la modification du règlement Stcrt. 2026, 16532 n'a pas été lue).", "Nel 2026 il termine della domanda è stato prorogato dal 15 maggio a lunedì 18 maggio, perché venerdì 15 maggio, giorno dopo l'Ascensione, è legalmente equiparato a festivo. La data di riferimento è rimasta il 15 maggio 2026. Fonte: RVO (la modifica del regolamento Stcrt. 2026, 16532 non è stata letta).")),
]


